from random import randbytes, randint, choice
from Crypto.Util.number import sieve_base as primes, bytes_to_long, getPrime
import os

flag = b'xxx'


def is_prime(n):
    if n == 2 or n == 3:
        return True

    if n < 2 or n % 2 == 0:
        return False

    bitsize = n.bit_length()
    if bitsize >= 1536:
        k = 3
    elif bitsize >= 1024:
        k = 4
    elif bitsize >= 512:
        k = 7
    else:
        k = 10

    # s=log(n)
    s, d = 0, n - 1
    while d % 2 == 0:
        s, d = s + 1, d // 2

    for _ in range(k):
        a = randint(2, n - 2)
        x = pow(a, d, n)

        if x == 1 or x == n - 1:
            continue

        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True


def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a


def lcm(a, b):
    return (a * b) // gcd(a, b)


def myPrime(bits):
    while True:
        n = 2
        while n.bit_length() < bits:
            n *= choice(primes)
            # random的，也就是说r并不能直接求出来，只知道是某些素数的乘积
        if is_prime(n + 1):
            return n + 1


def generate_keys(bits):
    wish = b'Be a good ctfer.'
    seed = int.from_bytes(randbytes(bits // 8), byteorder="little")
    p = (seed + randint(-10e6, 10e6)) | 1
    while not is_prime(p):
        p += 2

    q = (seed + randint(-10e7, 10e7)) | 1
    while not is_prime(q):
        q += 2

    r = myPrime(bits)
    # r-1是一系列素数的乘积

    n = p * q * r

    e = getPrime(40)
    enc_wish = pow(bytes_to_long(wish), e, r)

    return (n, e, enc_wish)


def encrypt(m, e, n):
    return pow(m, e, n)


if __name__ == '__main__':
    n, e, enc_wish = generate_keys(1024)
    pad_flag = os.urandom(240) + flag
    c = encrypt(bytes_to_long(pad_flag), e, n)
    print(f'n = {n}')
    print(f'c = {c}')
    print(f'enc_wish = {enc_wish}')

